{"source":"import json, sys
from datetime import datetime, timezone


def parse_dt(s):
    s2 = s.replace("Z", "+00:00")
    return datetime.fromisoformat(s2)


data = json.load(open(sys.argv[1]))
as_of = parse_dt(data["as_of"])

items = []
for r in data.get("reminders", []):
    if r.get("completed"):
        continue
    due = r.get("due")
    if due is None:
        continue
    if not isinstance(due, str):
        continue
    try:
        dt = parse_dt(due)
    except ValueError:
        continue
    if dt.tzinfo is None:
        continue  # naive, skip
    if dt > as_of:
        continue
    dt_utc = dt.astimezone(timezone.utc)
    items.append({
        "id": r["id"],
        "title": r["title"],
        "due_utc": dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "_dt": dt_utc,
    })

items.sort(key=lambda x: (x["_dt"], x["id"]))
out = [{"id": x["id"], "title": x["title"], "due_utc": x["due_utc"]} for x in items]
print(json.dumps(out, ensure_ascii=False))"}

